function getTodayChallenges(){
  var dayIdx=Math.floor(Date.now()/86400000);
  var result=[];
  for(var i=0;i<3;i++)result.push(DAILY_CHALLENGES[(dayIdx+i)%DAILY_CHALLENGES.length]);
  return result;
}

